// AI provider keys, kept on this device only and never sent to our server.
// They are encrypted with AES-GCM before they are stored. The encryption key is generated by the
// browser as non-extractable: scripts can use it to decrypt, but cannot read or copy it out, and it
// never appears in storage as text. Everything lives in IndexedDB (`oc-vault`). Tabs tell each other
// about changes over a BroadcastChannel, so a key added in one tab shows up in the others.
// If IndexedDB or WebCrypto is unavailable (some private windows), keys fall back to localStorage.

const LEGACY = 'oc-keys', FALLBACK = 'oc-keys-plain';
const channel = typeof BroadcastChannel === 'function' ? new BroadcastChannel('oc-keys') : null;

let dbp = null;
function db(){
  return dbp ||= new Promise(resolve => {
    try {
      const req = indexedDB.open('oc-vault', 1);
      req.onupgradeneeded = () => req.result.createObjectStore('kv');
      req.onsuccess = () => resolve(req.result);
      req.onerror = req.onblocked = () => resolve(null);
    } catch { resolve(null); }
  });
}
const idb = (d, mode, fn) => new Promise((resolve, reject) => {
  const tr = d.transaction('kv', mode), r = fn(tr.objectStore('kv'));
  tr.oncomplete = () => resolve(r?.result);
  tr.onerror = tr.onabort = () => reject(tr.error);
});

// The device's encryption key: created once, stored as a non-extractable CryptoKey object
let cryptoKeyP = null;
function deviceKey(d){
  return cryptoKeyP ||= (async () => {
    let k = await idb(d, 'readonly', s => s.get('cryptokey'));
    if (!k) {
      k = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
      await idb(d, 'readwrite', s => s.put(k, 'cryptokey'));
    }
    return k;
  })();
}
const secure = async () => { const d = await db(); return d && crypto?.subtle ? d : null; };

const lsGet = (store, k) => { try { return JSON.parse(store.getItem(k) || 'null'); } catch { return null; } };
const lsDel = (store, k) => { try { store.removeItem(k); } catch {} };

async function read(){
  const d = await secure();
  if (!d) return lsGet(localStorage, FALLBACK) || {};
  const box = await idb(d, 'readonly', s => s.get('keys'));
  if (!box) return {};
  const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: box.iv }, await deviceKey(d), box.data);
  return JSON.parse(new TextDecoder().decode(plain)) || {};
}
async function write(keys){
  const d = await secure();
  const clean = Object.fromEntries(Object.entries(keys || {}).filter(([, v]) => typeof v === 'string' && v));
  if (!d) { try { localStorage.setItem(FALLBACK, JSON.stringify(clean)); } catch {} return; }
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const data = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await deviceKey(d), new TextEncoder().encode(JSON.stringify(clean)));
  await idb(d, 'readwrite', s => s.put({ iv, data }, 'keys'));
  lsDel(localStorage, FALLBACK);
}

/** Loads the saved keys. Keys stored the old way (plain text) are moved into the vault and erased. */
export async function loadKeys(){
  let keys = {};
  try { keys = await read(); } catch (e) { console.warn('[keys] could not read the vault', e); }
  const old = { ...(lsGet(localStorage, LEGACY) || {}), ...(lsGet(sessionStorage, LEGACY) || {}) };
  if (Object.keys(old).length) {
    keys = { ...old, ...keys };
    try { await write(keys); lsDel(localStorage, LEGACY); lsDel(sessionStorage, LEGACY); } catch (e) { console.warn('[keys] migration failed', e); }
  }
  return keys;
}

/** Saves the keys and tells the other open tabs. */
export async function saveKeys(keys){
  try { await write(keys); } catch (e) { console.warn('[keys] could not save', e); throw e; }
  channel?.postMessage('changed');
}

/** Erases every saved key on this device (all tabs). */
export async function clearKeys(){
  await saveKeys({});
}

/** Calls `fn` when another tab changes the keys. */
export function onKeysChanged(fn){
  channel?.addEventListener('message', () => fn());
}
